  "confidence": "high",
  "uncertainties": [],
  "risk": {
    "level": "medium",
    "touches": [
      "wallet",
      "rpc_api",
      "other"
    ],
    "why": "A bug in keypath or descriptor multipath parsing and reconstruction could lead to incorrect key derivation, mismatched scriptPubKeys, or wallet load failures."
  }
}
